import json
with open('fees.json') as f:
    fees = json.load(f)

def matches(rule, m):
    if rule['account_type'] and m['account_type'] not in rule['account_type']:
        return False
    if rule['capture_delay'] is not None and rule['capture_delay'] != m['capture_delay']:
        return False
    if rule['merchant_category_code'] and m['merchant_category_code'] not in rule['merchant_category_code']:
        return False
    return True

m = {'merchant':'Martinis_Fine_Steakhouse','capture_delay':'immediate','merchant_category_code':5812,'account_type':'H'}
app = [r for r in fees if matches(r, m)]
print("matching rules:", len(app))
from collections import Counter
print(Counter(str(r['monthly_fraud_level']) for r in app))
for r in app:
    if r['monthly_fraud_level'] is not None:
        print(r['ID'], r['card_scheme'], r['monthly_fraud_level'], r['monthly_volume'], r['is_credit'], r['aci'], r['fixed_amount'], r['rate'])

